  function renderCalendarSettings(){const section=$('#settings-calendar');if(!section)return;section.innerHTML=`<div class="group-head"><h2>Kalendarz</h2><p>Kategorie oraz kopie danych kalendarza</p></div><div class="settings-card calendar-settings-card"><div class="setting-row stack"><span><b>Kategorie</b><small>Edytuj skrót, nazwę, kolor, godziny i wydarzenia całodniowe</small></span><div class="category-manager">${categories.map(cat=>`<article class="category-row" data-settings-category="${safe(cat.id)}"><label class="category-field category-code"><small>Skrót</small><input type="text" maxlength="8" value="${safe(cat.code)}" aria-label="Skrót"></label><label class="category-field category-name"><small>Nazwa</small><input type="text" maxlength="40" value="${safe(cat.name)}" aria-label="Nazwa"></label><label class="category-field category-color"><small>Kolor</small><input type="color" value="${safe(cat.color)}" aria-label="Kolor"></label><label class="category-field"><small>Od</small><input type="time" value="${safe(cat.start)}" aria-label="Od"></label><label class="category-field"><small>Do</small><input type="time" value="${safe(cat.end)}" aria-label="Do"></label><label class="category-all-day"><input type="checkbox" ${cat.allDay?'checked':''}><span>Cały dzień</span></label>${iconButton('trash','Usuń kategorię','class="danger"')}</article>`).join('')}<div class="category-manager-actions">${iconButton('plus','Dodaj kategorię','data-settings-add-category')}${iconButton('save','Zapisz kategorie','data-settings-save-categories')}</div></div></div><div class="setting-row stack"><span><b>Import i eksport</b><small>Pełna kopia wydarzeń i kategorii w pliku JSON</small></span><div class="calendar-settings-actions">${iconButton('download','Eksportuj kalendarz','data-calendar-export')}<label class="icon-action" aria-label="Importuj kalendarz" title="Importuj kalendarz"><svg aria-hidden="true"><use href="/icons.svg#upload"/></svg><input type="file" accept="application/json,.json" data-calendar-import></label></div></div></div>`;
    $$('[data-settings-category]',section).forEach(row=>$('.danger',row).onclick=()=>{if(categories.length<2)return;categories=categories.filter(cat=>cat.id!==row.dataset.settingsCategory);persist();renderCalendarSettings()});$('[data-settings-add-category]',section).onclick=()=>{categories.push({id:crypto.randomUUID(),code:'NOWA',name:'Nowa kategoria',color:'#4fdde5',start:'09:00',end:'10:00',allDay:false});persist();renderCalendarSettings()};$('[data-settings-save-categories]',section).onclick=()=>{$$('[data-settings-category]',section).forEach(row=>{const inputs=$$('input',row),cat=category(row.dataset.settingsCategory);cat.code=inputs[0].value.trim().toUpperCase()||'KAT';cat.name=inputs[1].value.trim()||cat.code;cat.color=inputs[2].value;cat.start=inputs[3].value||'09:00';cat.end=inputs[4].value||'10:00';cat.allDay=inputs[5].checked});persist();renderCalendarSettings();renderCalendar()};$('[data-calendar-export]',section).onclick=exportCalendar;$('[data-calendar-import]',section).onchange=event=>{const file=event.target.files?.[0];if(file)importCalendar(file)}}
  const renderCalendarSettingsBase=renderCalendarSettings;renderCalendarSettings=function(){renderCalendarSettingsBase();const section=$('#settings-calendar');const actions=$('.calendar-settings-actions',section);if(!actions)return;const makeAction=(icon,title,subtitle)=>{const button=document.createElement('button');button.type='button';button.className='calendar-transfer-action';button.innerHTML=`<svg aria-hidden="true"><use href="/icons.svg#${icon}"/></svg><span><b>${title}</b><small>${subtitle}</small></span>`;return button};const exportButton=makeAction('download','Eksportuj kalendarz','Zapisz kopię JSON na urządzeniu');exportButton.onclick=exportCalendar;const importLabel=document.createElement('label');importLabel.className='calendar-transfer-action';importLabel.innerHTML='<svg aria-hidden="true"><use href="/icons.svg#upload"/></svg><span><b>Importuj kalendarz</b><small>Wczytaj kopię JSON z urządzenia</small></span><input type="file" accept="application/json,.json">';$('input',importLabel).onchange=event=>{const file=event.target.files?.[0];if(file)importCalendar(file)};actions.replaceChildren(exportButton,importLabel);const managerActions=$('.category-manager-actions',section);if(managerActions){const add=makeAction('plus','Dodaj kategorię','Dodaj nowy rodzaj wydarzenia'),saveCategories=makeAction('save','Zapisz kategorie','Zapisz wprowadzone zmiany');add.onclick=()=>{categories.push({id:crypto.randomUUID(),code:'NOWA',name:'Nowa kategoria',color:'#4fdde5',start:'09:00',end:'10:00',allDay:false});persist();renderCalendarSettings()};saveCategories.onclick=()=>{$$('[data-settings-category]',section).forEach(row=>{const inputs=$$('input',row),cat=category(row.dataset.settingsCategory);cat.code=inputs[0].value.trim().toUpperCase()||'KAT';cat.name=inputs[1].value.trim()||cat.code;cat.color=inputs[2].value;cat.start=inputs[3].value||'09:00';cat.end=inputs[4].value||'10:00';cat.allDay=inputs[5].checked});persist();renderCalendarSettings();renderCalendar()};managerActions.replaceChildren(add,saveCategories)}};
  const settingsIndex=$('.settings-index nav'),settingsContent=$('#settingsContent');if(settingsIndex&&settingsContent){const button=document.createElement('button');button.type='button';button.dataset.settingsTarget='settings-calendar';button.textContent='Kalendarz';const codesButton=$('[data-settings-target="settings-codes"]',settingsIndex);settingsIndex.insertBefore(button,codesButton);const section=document.createElement('section');section.id='settings-calendar';section.className='settings-section';settingsContent.insertBefore(section,$('#settings-codes'));button.onclick=()=>section.scrollIntoView({behavior:'smooth',block:'start'});renderCalendarSettings()}
  const giftSettingsButton=$('[data-settings-target="settings-thresholds"]',settingsIndex);if(giftSettingsButton)giftSettingsButton.textContent='Ustawienia prezentów';
  const settingsIconMap={'settings-chat':'chat','settings-appearance':'viewers','settings-tts':'play','settings-thresholds':'filter','settings-mixer':'radio','settings-calendar':'calendar','settings-usage':'timer','settings-codes':'shield','settings-account':'info','settings-data':'archive'};
  if(settingsIndex)$$('[data-settings-target]',settingsIndex).forEach(button=>{const label=button.textContent.trim(),iconName=settingsIconMap[button.dataset.settingsTarget]||'settings';button.innerHTML=`<svg aria-hidden="true"><use href="/icons.svg#${iconName}"/></svg><span>${label}</span>`});
  let activeSettingsTarget='settings-chat';
  function showSettingsCategory(target,{focus=false}={}){
    const section=$(`#${target}`);if(!section)return;
    activeSettingsTarget=target;
    $$('.settings-section',settingsContent).forEach(item=>item.classList.toggle('settings-category-hidden',item!==section));
    $$('[data-settings-target]',settingsIndex).forEach(button=>button.classList.toggle('active',button.dataset.settingsTarget===target));
    settingsContent.scrollTop=0;
    if(focus)requestAnimationFrame(()=>setTimeout(()=>$('#accountProfileName')?.focus(),80));
  }
  if(settingsIndex&&settingsContent){$$('[data-settings-target]',settingsIndex).forEach(button=>button.onclick=()=>showSettingsCategory(button.dataset.settingsTarget));showSettingsCategory(activeSettingsTarget)}
  function switchWorkspace(name){
    activeWorkspace=name;
    $$('.workspace-panel',main).forEach(panel=>panel.hidden=panel.dataset.workspacePanel!==name);$$('.round-nav [data-workspace]').forEach(button=>button.classList.toggle('active',button.dataset.workspace===name));
    supportQr.hidden=!['chat','patreon'].includes(name);
    const moduleMode=isDesktop&&['archive','notes','calendar','radio'].includes(name);desktopSidebar?.classList.toggle('settings-mode',moduleMode);desktopSidebar?.classList.toggle('module-mode',moduleMode);if(desktopSettingsSidebar)desktopSettingsSidebar.hidden=true;moduleSidebar.hidden=!moduleMode;if(moduleMode)renderModuleSidebar(name);
    const stats=$('#stats');if(stats)stats.hidden=name!=='chat';renderLiveTools();
    window.dispatchEvent(new CustomEvent('cttm-workspace-change',{detail:name}));
    if(name==='archive'){$('#refreshArchive')?.click();requestAnimationFrame(()=>renderModuleSidebar('archive'))}
    if(name==='notes'){notes.hidden=false;$('#notesSearch')?.dispatchEvent(new Event('input'));}
    if(name==='calendar')renderCalendar();if(name==='radio'){renderRadio();void loadRadioPlaylist(selectedRadioStation)}if(name==='patreon'){markPatreonSeen();void loadPatreonPosts()}
  }
  function switchTopTab(name){giveawayBackdrop.hidden=true;if(!timerAlarmActive)timerBackdrop.hidden=true;$$('.tab').forEach(panel=>panel.classList.toggle('active',panel.id===name));$$('.round-nav button').forEach(button=>button.classList.toggle('active',button.dataset.tab===name));desktopSidebar?.classList.toggle('settings-mode',name==='settings');desktopSidebar?.classList.remove('module-mode');if(desktopSettingsSidebar)desktopSettingsSidebar.hidden=name!=='settings';moduleSidebar.hidden=true;supportQr.hidden=name!=='chat';if(name==='settings')showSettingsCategory(activeSettingsTarget);if(name==='chat')switchWorkspace('chat')}
  $$('.round-nav button:not([data-timer]):not([data-giveaway])').forEach(button=>button.onclick=()=>{if(button.dataset.workspace){switchTopTab('chat');switchWorkspace(button.dataset.workspace)}else switchTopTab(button.dataset.tab)});
  window.addEventListener('cttm-open-account-settings',()=>{switchTopTab('settings');showSettingsCategory('settings-account',{focus:true})});
  $('.brand').onclick=()=>switchTopTab('chat');
  window.addEventListener('cttm-calendar-sync',event=>{const next=event.detail||{},nextCategories=Array.isArray(next.categories)?next.categories:categories,nextEvents=Array.isArray(next.events)?next.events:events,changed=JSON.stringify(nextCategories)!==JSON.stringify(categories)||JSON.stringify(nextEvents)!==JSON.stringify(events);categories=nextCategories;events=nextEvents;localStorage.setItem('cttm-calendar-categories',JSON.stringify(categories));localStorage.setItem('cttm-calendar-events',JSON.stringify(events));if(changed){if(calendarOverlay.mode==='edit')calendarNeedsRender=true;else{renderCalendar();renderCalendarSettings()}}refreshDesktopWidget()});
  new MutationObserver(records=>{if(records.some(record=>record.attributeName==='data-theme'))refreshDesktopWidget()}).observe(document.documentElement,{attributes:true,attributeFilter:['data-theme']});
  renderCalendar();refreshDesktopWidget();switchWorkspace('chat');window.setTimeout(()=>void loadPatreonPosts({force:true}),3000);window.setInterval(()=>void loadPatreonPosts({force:true}),300000);window.setInterval(()=>{if(activeWorkspace==='radio')void loadRadioPlaylist(selectedRadioStation,{force:true})},RADIO_PLAYLIST_TTL);
